  for (const e of ups.filter(x => x.section === 'DATASHEETS')) {
    const t = String(e.title).trim(), instr = String(e.instr).trim();
    let m;
    if ((m = /^(.+?)(?:,| –| -) Keywords(?: Section)?$/i.exec(t)) && (m = Object.assign(m, { add: /^Add ['‘]([^'’]+)['’]\.?$/i.exec(instr) })).add) {
